TARGETS = {
    "core": {
        "public_headers": ["core/include/api.h"],
        "private_headers": ["core/src/impl.h"],
    },
    "app": {
        "public_headers": [],
        "private_headers": ["app/src/app_detail.h"],
    },
}

GOOD_INCLUDES = {
    "app": ["core/include/api.h", "app/src/app_detail.h"],
    "core": ["core/include/api.h", "core/src/impl.h"],
}
BAD_INCLUDES = {
    "app": ["core/include/api.h", "core/src/impl.h"],
}


def owner_of(h, targets):
    for t, spec in targets.items():
        if h in spec["public_headers"]:
            return t, "PUBLIC"
        if h in spec["private_headers"]:
            return t, "PRIVATE"
    return None, None


def check(includes):
    problems, notes = [], []
    for t in sorted(includes):
        for h in includes[t]:
            o, kind = owner_of(h, TARGETS)
            if o is None:
                problems.append(("HS002", t, h, "头文件不属于任何目标：可能是系统头或未声明的依赖"))
            elif kind == "PRIVATE" and o != t:
                problems.append(("HS001", t, h, "包含了 %s 的 PRIVATE 头：该头不在 %s 的 include 路径中（target_include_directories 用了 PRIVATE）" % (o, t)))
            else:
                notes.append((t, h, "%s(%s)" % (o, kind)))
    return problems, notes


for label, inc, want_clean in (("正例", GOOD_INCLUDES, True), ("反例", BAD_INCLUDES, False)):
    problems, notes = check(inc)
    print("[%s] 目标=%s" % (label, sorted(inc)))
    for t, h, info in notes:
        print("  OK      %-5s 包含 %-24s 归属=%s" % (t, h, info))
    for code, t, h, msg in problems:
        print("  %s  %-5s 包含 %-24s %s" % (code, t, h, msg))
    print("  -> 违规数=%d" % len(problems))
    assert (not problems) == want_clean, "判定与预期不符: " + label

print("[判定] 检查器：正例 0 违规、反例 1 违规 -> 可区分正反两组 = True")
